## Code Example
```javascript
// Pseudocode: basic blob counting and simple classifier usage
function countItems(frameROI, types) {
  const blobs = segmentByColorAndEdges(frameROI);
  const counts = {};
  for (const t of types) counts[t] = 0;
  for (const b of blobs) {
    const type = classifyBlob(b, t); // tiny CNN or heuristic
    if (type) counts[type] += 1;
  }
  return counts;
}
```

